    def list_things(self, offset: int = 0, limit: int = 50) -> Page[ThingRead]:
        """A page of things, by primary key."""
        page = self._uow.things.list(offset, limit)
        return Page(items=[self._read(entity) for entity in page.items], total=page.total, offset=page.offset, limit=page.limit)

    def update_thing(self, id: UUID, data: ThingUpdate) -> ThingRead:
        """Changes the given values of a Thing."""
        values = data.model_dump(exclude_unset=True)
        with self._uow.transaction():
            current = self._find(id)
            self._check(values, current)
            for name, value in values.items():
                setattr(current, name, value)
            updated = self._uow.things.update(current)
            return self._read(updated)

    def delete_thing(self, id: UUID) -> None:
        """Deletes a Thing."""
        with self._uow.transaction():
            current = self._find(id)
            self._uow.things.delete(current)

