"""Rows for the tests: valid values for every column, and the rows they point to."""

from datetime import date, datetime, time
from decimal import Decimal
from typing import Any
from uuid import UUID

from app.entities.empty import Empty
from app.entities.entry import Entry
from app.entities.kind import Kind
from app.entities.order import Order
from app.entities.thing import Thing
from app.unit_of_work import UnitOfWork


def new_thing(n: int = 1, **values: Any) -> Thing:
    """A valid Thing that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"token": UUID(int=n), "small": n, "num": n, "big": n, "price": Decimal(f"{n % 10000}.50"), "r": n + 0.5, "d": n + 0.5, "flag": True, "born": date(2026, 1, n % 28 + 1), "opens": time(12, n % 60), "opens_tz": time(12, n % 60), "at": datetime(2026, 1, n % 28 + 1, 12, 0, 0), "at_tz": datetime(2026, 1, n % 28 + 1, 12, 0, 0), "bin": bytes([n % 256]), "data": {"n": n}, "plain": {"n": n}, "feeling": "sad", "tags": [], "numbers": [], "ip": None, "span": None, "code": f"{n:05d}"[-5:], "note": f"note-{n}"}
    return Thing(**(defaults | values))


def add_thing(uow: UnitOfWork, n: int = 1) -> Thing:
    """A stored Thing."""
    return uow.things.insert(new_thing(n))


def new_kind(n: int = 1, **values: Any) -> Kind:
    """A valid Kind that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"code": f"code-{n}", "day": date(2026, 1, n % 28 + 1), "label": f"label-{n}"}
    return Kind(**(defaults | values))


def add_kind(uow: UnitOfWork, n: int = 1) -> Kind:
    """A stored Kind."""
    return uow.kinds.insert(new_kind(n))


def new_order(n: int = 1, **values: Any) -> Order:
    """A valid Order that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"user": f"user-{n}", "group": n, "customer_name": f"customername-{n}", "class_": f"class-{n}", "metadata_": f"metadata-{n}", "date": date(2026, 1, n % 28 + 1), "time": time(12, n % 60), "text": f"text-{n}", "list": f"list-{n}", "str": f"str-{n}", "int": n, "due_date": date(2026, 1, n % 28 + 1), "closes_at": time(12, n % 60), "kind_code": None, "kind_day": None, "thing_id": None, "parent_id": None}
    return Order(**(defaults | values))


def add_order(uow: UnitOfWork, n: int = 1) -> Order:
    """A stored Order."""
    return uow.order.insert(new_order(n))


def new_entry(n: int = 1, **values: Any) -> Entry:
    """A valid Entry that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"message": f"message-{n}"}
    return Entry(**(defaults | values))


def add_entry(uow: UnitOfWork, n: int = 1) -> Entry:
    """A stored Entry, with the rows it points to."""
    parent_0 = add_order(uow, n)
    return uow.entries.insert(new_entry(n, order_id=parent_0.id))


def new_empty(n: int = 1, **values: Any) -> Empty:
    """A valid Empty that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"note": f"note-{n}"}
    return Empty(**(defaults | values))


def add_empty(uow: UnitOfWork, n: int = 1) -> Empty:
    """A stored Empty."""
    return uow.empties.insert(new_empty(n))
